(7416071, 1169587, 150277, '<td valign="top">Great shot of a fish.  The tail is like glass.</td>', 'Great shot of a fish.  The tail is like glass.', '2015-11-13 13:26:19.000000', NULL, 1),
(7416072, 1169833, 150277, '<td valign="top">So cute, I like the choice of composition.</td>', 'So cute, I like the choice of composition.', '2015-11-13 13:26:28.000000', NULL, 1),
(7416073, 1169381, 150277, '<td valign="top">Sweet.  I like the choice of a bench.</td>', 'Sweet.  I like the choice of a bench.', '2015-11-13 13:27:24.000000', NULL, 1),
