(7416089, 1169533, 19944, '<td valign="top">I feel like the focus point is the leaves on the ground, rather than yeller</td>', 'I feel like the focus point is the leaves on the ground, rather than yeller', '2015-11-13 14:56:27.000000', NULL, 1),
(7416090, 1169633, 19944, '<td valign="top">I don''t get it.</td>', 'I don''t get it.', '2015-11-13 14:59:03.000000', NULL, 1),
(7416129, 1169684, 59029, '<td valign="top">Let me guess....your owner''s site name is Tiberius!</td>', 'Let me guess....your owner''s site name is Tiberius!', '2015-11-13 17:59:53.000000', NULL, 1),
(7416130, 1169599, 59029, '<td valign="top">Uhm looks like a pitbull...a breed I''ve not had many good experiences with sadly.  Still a nice port.</td>', 'Uhm looks like a pitbull...a breed I''ve not had many good experiences with sadly.  Still a nice port.', '2015-11-13 18:00:41.000000', NULL, 1),
(7416131, 1169530, 59029, '<td valign="top">Hard to believe this breed originated in Canada!  Cool port though</td>', 'Hard to believe this breed originated in Canada!  Cool port though', '2015-11-13 18:04:14.000000', NULL, 1),
(7416162, 1169660, 15163, '<td valign="top">beautiful dogs... but more a portrait of the man to me</td>', 'beautiful dogs... but more a portrait of the man to me', '2015-11-14 08:17:59.000000', NULL, 1),
(7416163, 1169587, 15163, '<td valign="top">GREAT change from dogs and cats, excellent focus and depth of field.  Never really think of fish as pets because.. well they are hard to "pet".</td>', 'GREAT change from dogs and cats, excellent focus and depth of field.  Never really think of fish as pets because.. well they are hard to "pet".', '2015-11-14 08:23:20.000000', NULL, 1),
(7416164, 1169533, 15163, '<td valign="top">Ground was in clearer focus than yeller in this photo</td>', 'Ground was in clearer focus than yeller in this photo', '2015-11-14 08:33:44.000000', NULL, 1),
(7416182, 1169703, 65234, '<td valign="top">Beautifully lit and composed so the dog is the star of the show. And a VERY patient dog,  too!</td>', 'Beautifully lit and composed so the dog is the star of the show. And a VERY patient dog,  too!', '2015-11-14 16:02:25.000000', NULL, 1),
(7416183, 1169608, 65234, '<td valign="top">That ear is just great!  Not sure I would have used that backdrop color with that dog,  but the image is well done.</td>', 'That ear is just great!  Not sure I would have used that backdrop color with that dog,  but the image is well done.', '2015-11-14 16:06:03.000000', NULL, 1),
(7416184, 1169660, 65234, '<td valign="top">The man or the puppies? Maybe both. Nicely done,  although if I had an armload of pups I''d look a lot happier!</td>', 'The man or the puppies? Maybe both. Nicely done,  although if I had an armload of pups I''d look a lot happier!', '2015-11-14 16:08:03.000000', NULL, 1),
(7416185, 1169587, 65234, '<td valign="top">Nice job on the detail and lighting here. Which ain''t easy with a fish for a model.</td>', 'Nice job on the detail and lighting here. Which ain''t easy with a fish for a model.', '2015-11-14 16:10:14.000000', NULL, 1),
(7416186, 1169539, 65234, '<td valign="top">She looks quite comfy and stands out beautifully from the background. I''d desaturate the blue/cyan reflected bits.</td>', 'She looks quite comfy and stands out beautifully from the background. I''d desaturate the blue/cyan reflected bits.', '2015-11-14 16:14:48.000000', NULL, 1),
(7416271, 1169804, 65234, '<td valign="top">Spooky, as a black cat should be. Well, sometimes, anyway ;-) I like the "rising out of the inky darkness" idea, although I think I want the ears more detailed. Or the whole face less detailed and only the eyes glowing (though that may stray too far from being a portrait).</td>', 'Spooky, as a black cat should be. Well, sometimes, anyway ;-) I like the "rising out of the inky darkness" idea, although I think I want the ears more detailed. Or the whole face less detailed and only the eyes glowing (though that may stray too far from being a portrait).', '2015-11-15 10:59:43.000000', NULL, 1),
(7416272, 1169818, 65234, '<td valign="top">Gotta'' love a cocked, curious head. Love the perspective; as a giant dog owner I know this is not exaggerating the size of the dog!</td>', 'Gotta'' love a cocked, curious head. Love the perspective; as a giant dog owner I know this is not exaggerating the size of the dog!', '2015-11-15 11:01:31.000000', NULL, 1),
(7416273, 1169540, 65234, '<td valign="top">Aww, a bunny!  And a young-looking one at that. Very nice detail on the face. Crop feels a little awkward to me; I think I prefer the whole rabbit or just the head. I might''ve angled the bunny a bit more towards the camera so the rear fit in the frame. Love that little face, though :-)</td>', 'Aww, a bunny!  And a young-looking one at that. Very nice detail on the face. Crop feels a little awkward to me; I think I prefer the whole rabbit or just the head. I might''ve angled the bunny a bit more towards the camera so the rear fit in the frame. Love that little face, though :-)', '2015-11-15 11:04:51.000000', NULL, 1),
(7416274, 1169599, 65234, '<td valign="top">Looks like a wise elder statesman.</td>', 'Looks like a wise elder statesman.', '2015-11-15 11:05:27.000000', NULL, 1),
(7416275, 1169381, 65234, '<td valign="top">Great pose! Really like the scale the bench gives to the dog. Feels off-kilter looking at the baseboard and floor, though I can see the seat of the bench is straight in relation to the frame. I''d almost rather the bench look crooked, but I know someone will mind no matter what you line up with ;-)</td>', 'Great pose! Really like the scale the bench gives to the dog. Feels off-kilter looking at the baseboard and floor, though I can see the seat of the bench is straight in relation to the frame. I''d almost rather the bench look crooked, but I know someone will mind no matter what you line up with ;-)', '2015-11-15 11:09:24.000000', NULL, 1),
(7416276, 1169835, 65234, '<td valign="top">Sweet face and nice detail. I''d probably burn the eyes a tiny bit. They look washed out on my screen.</td>', 'Sweet face and nice detail. I''d probably burn the eyes a tiny bit. They look washed out on my screen.', '2015-11-15 11:14:14.000000', NULL, 1),
(7416279, 1169833, 65234, '<td valign="top">Cute little thing :-)  With a nice, simple chair to pose on. I''d clone out that light reflection on the wall, or crop it out.</td>', 'Cute little thing :-)  With a nice, simple chair to pose on. I''d clone out that light reflection on the wall, or crop it out.', '2015-11-15 11:16:30.000000', NULL, 1),
(7416280, 1169710, 65234, '<td valign="top">Pose, detail and backdrop are all nice. Light looks very harsh. I''d prefer softer shadows (or fill light from the side to lessen them in the first place), and the pupils should look dark.</td>', 'Pose, detail and backdrop are all nice. Light looks very harsh. I''d prefer softer shadows (or fill light from the side to lessen them in the first place), and the pupils should look dark.', '2015-11-15 11:18:51.000000', NULL, 1),
(7416281, 1169533, 65234, '<td valign="top">The pose is OK, but the focus is on the leaves instead of the dog''s eyes. I infinitely prefer in a portrait to have sharp eyes so I can connect with the subject.</td>', 'The pose is OK, but the focus is on the leaves instead of the dog''s eyes. I infinitely prefer in a portrait to have sharp eyes so I can connect with the subject.', '2015-11-15 11:20:38.000000', NULL, 1),
(7416282, 1169682, 65234, '<td valign="top">Cute dog and pose, but not sharply focused, which I strongly prefer in a portrait (particularly the eyes).</td>', 'Cute dog and pose, but not sharply focused, which I strongly prefer in a portrait (particularly the eyes).', '2015-11-15 11:22:00.000000', NULL, 1),
